from typing import List

def solve(n: int, k: int, a: List[int]) -> str:
    if gcd(*a) > 1:
        return "NO"

    ans = []
    for i in range(n):
        if gcd(a[i], k) == 1:
            ans.append((a[i] + 1, '\'\'' + str((int(a[i]) + 1) // k) + '\''))  # Replace remainder with an arrow symbol
            a[i] += 1
    if a[0] == 1:
        return "YES\n" + "\n".join([f"{i[1]} {i[0]}" for i in ans])
    else:
        return "NO"


