from typing import List
import heapq

def assign_colors(edges: List[List[int]], colors: List[int]) -> str:
    def dijkstra(graph, start):
        n = len(graph)
        distances = [float('inf')] * n
        distances[start] = 0
        heap = [(0, start)]
        visited = [False] * n
        result = []

        while heap:
            current_distance, u = heapq.heappop(heap)
            if visited[u]:
                continue
            visited[u] = True
            result.append((u, distances[u]))

            for v, weight in graph[u]:
                if not visited[v]:
                    new_distance = current_distance + weight
                    if new_distance < distances[v]:
                        distances[v] = new_distance
                        heapq.heappush(heap, (new_distance, v))

        return result

    num_nodes = len(edges) + 1
    edges_with_colors = [[[] for _ in range(num_nodes)] for _ in range(num_nodes)]
    colors_map = {color: [] for color in range(9)}

    for u, v in edges:
        edges_with_colors[u-1][v-1].append(colors[u-1])
        edges_with_colors[v-1][u-1].append(colors[v-1])
        colors_map[colors[u-1]].append((u, v))
        colors_map[colors[v-1]].append((v, u))

    final_result = [["1 2"]]  # Start with a dummy node connected to both 1 and 2 (couldn't make the statement true with just a single edge)
    for node in range(2, num_nodes):
        for color in range(1, 6):
            current_edge = [("1", str(node)), ("2", str(node))]
            for i, j in colors_map[color]:
                if graph[i-1][j-1]:
                    current_edge.append((str(i), str(j)))
                    color_edges = edges_with_colors[i-1][j-1]
                    for i in reversed(range(len(color_edges))):
                        color_entry = color_edges[i]
                        if color_entry == color:
                            break
                        current_edge[-1 if len(color_edges) == 1 else i + 1].append("0")
            final_result.append(" ".join(str(x) for x in current_edge))

    return "\n".join(map(str, final_result))

