import numpy as np

def is_tower_valid(tower):
    num_levels = len(tower)
    valid_levels = 0
    for i in range(num_levels-1, 0, -1):
        if tower[i] == tower[i-1] == tower[i-2]:
            valid_levels += 1
    if min(valid_levels, num_levels - valid_levels) == 1 and tower[0] != 'G' and tower[0] != 'R':
        return False
    return valid_levels > num_levels//2 + 1

def expected_minutes(tower):
    num_blocks = 0
    valid_blocks = 0
    for block in tower:
        if block in 'RGB':
            num_blocks += 1
            if block in 'RB':
                valid_blocks += 1
    return (valid_blocks - num_blocks) / (num_blocks / 2 + 1)

def solve(n, tower):
    num_levels = [1] * n
    for i in range(n-1, -1, -1):
        num_current_level = 1
        level = tower[i]
        if i == 0:
            bottom = tower[-1]
            if bottom == 'R' or bottom == 'B':
                num_current_level = 3 if bottom == 'R' else 3
        while level == 'R':
            level = tower[i-1]
            num_current_level += 1
        if level == 'B':
            level = tower[i-1]
            num_current_level += num_current_level % 3
        if level == 'G':
            if i > 0:
                top = tower[i-1]
                if top == 'R':
                    level = 'G'
                else:
                    if num_current_level < 2:
                        level = 'G'
        if level == 'B':
            if i > 0:
                top = tower[i-1]
                if top == 'B':
                    level = 'G'
                else:
                    level = 'B'
        num_levels[i] = num_current_level
    total_minutes = 0
    for i, num_blocks in enumerate(num_levels, 1):
        valid_minutes = expected_minutes([t for t in range(n-i+1)])
        if not is_tower_valid([t for t in range(n-i+1)]):
            return 0
        total_minutes += n-i+1 * math.floor(num_blocks * valid_minutes)
    return total_minutes

