def min_repaints(N, M, layout):
    direction = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    repaints = 0

    def within_grid(x, y):
        return 0 <= x < N and 0 <= y < M

    def is_linked(i, j):
        current = layout[i][j]
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            for dx, dy in direction:
                nx, ny = x + dx, y + dy
                if within_grid(nx, ny) and layout[nx][ny] != current:
                    return False
            stack.extend([(x, y), (x + dx, y), (x, y + dy), (x + dx, y + dy)])
        return all(layout[i][j] == layout[x][y] for i, j in stack)

    def mark(i, j):
        layout[i][j] = '*'

    def unmark(i, j):
        layout[i][j] = layout.get(i, {}).get(j, ' ')

    def connected(i, j):
        stack = [(i, j)]
        previous = None
        while stack:
            x, y = stack.pop()
            if(previous is None):
                previous = x, y
            elif previous == (x, y):
                return True
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x + dx, y + dy
                if(within_grid(nx, ny) and layout[nx][ny] != '*'):
                    stack.append((nx, ny))
        return False

    def cut_square(i, j):
        for x, y in location:
            res = connected(i, j) and connected(x + i, y + j)
            if res:
                mark(x, y)
                while not connected(i, j):
                    m = x, y
                    for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                        nx, ny = x + dx, y + dy
                        if within_grid(nx, ny) and layout[nx][ny] == '*':
                            m = x, y = nx, ny
                    if connected(x, y) and connected(m[0], m[1]):
                        unmark(m[0], m[1])
                        break

    def apply_layout(i, j):
        connected(i, j), unmark(i, j), unmark(j, i), mark(i, j)

    for i in range(N):
        for j in range(M):
            if layout[i][j] == '*':
                location = []
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = i + dx, j + dy
                    if within_grid(nx, ny) and layout[nx][ny] == '*':
                        location.append((nx, ny))
                if len(location) > 1:
                    x, y = min(location, key=lambda x: (x[0], x[1]))
                    cut_square(x, y)

    for i in range(N-1, -1, -1):
        for j in range(M-1, -1, -1):
            apply_layout(i, j)
            if layout[i][j] != '*':
                repaints += 1
                break

    return repaints

