def is_possible(n, numbers):
    while True:
        # Check if we can reverse all zeros at the end
        if all(number == '0' for number in numbers):
            return 'YES'

        # Try to negate all numbers, except multiples of n
        modified_numbers = []
        for number in numbers:
            if '1' in number:
                modified_numbers.append('1')
            else:
                modified_numbers.append('0')

        # Shuffle indices to avoid treating two "1"s as two separate "0"s
        indices = list(range(n))
        random.shuffle(indices)
        for index in indices:
            if modified_numbers[index] == '0':
                continue

            # Generate all indexes for an even/odd turn
            even_indices = [i for i in range(0, n, 2)]
            odd_indices = [i for i in range(1, n, 2)]

            # Get an index of a "0" (inverse cycle)
            zero_index = -1
            for shift in odd_indices:
                if modified_numbers[shift] == '0':
                    zero_index = shift
                    break

            # There must be a "0" because we have a permutation
            if zero_index == -1:
                return 'NO'

            # Rotate zero_index back to its spot
            virtual_numbers = numbers[:]
            for _ in range(modified_numbers[zero_index]):
                virtual_numbers.pop(zero_index)
                zero_index = (zero_index + 1) % n

            # Make potentially reverseable numbers "1"
            for i in odd_indices:
                if modified_numbers[i] == '0':
                    virtual_numbers[i] = virtual_numbers[i] if virtual_numbers[i] == '1' else '0'

            modified_numbers = virtual_numbers[:]

        # Turn this numbers into "0"s of the already repeating "0"s skeleton
        for i in range(3, n):
            numbers = [round(sum(numb[:-i if i % 2 else i + 2]) / i, 10) if '1' in numb else '0' for numb in numbers]

        # Check if all zeros at the end are actually repeated
        if '0' in numbers:
            return 'YES'

        # If we're stuck at interfering numbers (0 then 0), return impossible
        if all(num == '0' and '0' in modified_numbers for num in modified_numbers):
            return 'NO'

