def parse_expression(expression):
    stack = []
    current = ''
    positive = True

    for char in expression:
        if char.isdigit():
            current += char
        else:
            if char == '-':
                if not positive:
                    stack.append(int(current, 10) if current else 0)
                positive = False
                current = ''
            elif char == '(':
                stack.append({
                    'type': 'term',
                    'value': current.strip()
                })
                current = ''
                positive = True
            elif char in '()+':
                if current:
                    stack.append(int(current, 10) if current else 0)
                current = ''
                if char == ')':
                    if stack[-1]['value'].replace('.', '', 1).isdigit():
                        number = stack.pop()
                        current = ''
                    else:
                        number = parse_expression(stack.pop()['value'])
                else:
                    number = int(char)
                if positive:
                    stack.append({"type": "term", "value": str(number)})
            elif char == '+':
                if stack[-1]['type'] in ['term', 'expression']:
                    if stack[-1]['value'].replace('.', '', 1).isdigit():
                        number = stack.pop()
                    else:
                        number = parse_expression(stack.pop()['value'])
                    if current:
                        current += ' ' + current
                    numbers = stack.pop()['value'].split()
                    numbers.append(current)
                    numbers.append("+" + str(number))
                    result = int(''.join(numbers), 10)
                    stack.append({"type": "term", "value": str(result)})
                    current = ''
                positive = False
            elif char == ' ':
                positive = True

    if current:
        if positive:
            number = int(current, 10) if current else 0
        else:
            if current:
                current = current.strip()
                if current.replace('.', '', 1).isdigit():
                    number = int(current, 10)
                else:
                    number = parse_expression(current)
            else:
                number = 0
        type = 'expression'
    else:
        if stack[-1]['type'] in ['term', 'expression']:
            if stack[-1]['value'].replace('.', '', 1).isdigit():
                number = int(stack.pop()['value'] if stack[-1]['type'] == 'term' else stack.pop()['value'].replace('.', '', 1))
            else:
                number = parse_expression(stack.pop()['value'])
        else:
            number = 0
        type = 'term'

    if type == 'term':
        numbers = stack.pop()['value'].split()
        numbers.append(str(number))
        result = int(''.join(numbers), 10)
        return result
    elif type == 'expression':
        return number

