def create_carpet(f, sides):
    graph = defaultdict(list)
    edges = set()
    for i in range(1, f + 1):
        for _ in range(sides[i-1]):
            u, v = map(lambda x: x - 1, list(map(int, input().split()))[1:])
            graph[u].append(v)
            graph[v].append(u)
            edges.add(tuple(sorted([u, v])))

    # Create a graph with a dual structure to allow multiple edges between same nodes
    dual_graph = defaultdict(list)
    dual_edges = set()

    for u, v in graph.items():
        for a in range(1, max(v) + 1):
            for e in ((u + a)[-1], (u + a)[0], (u - a)[-1], (u - a)[0]):
                if e != u and e not in graph and e not in dual_graph[u]:
                    dual_edges.add(tuple(sorted([u, e])))
                    dual_graph[u].append(e)
                    dual_graph[e].append(u)

    # Create the final graph to satisfy planarity and minimum perimeter
    valid_edges = []
    for u, v in edges:
        if v not in (u + 1, u - 1):
            valid_edges.append((u, v))

    while valid_edges:
        u, v = valid_edges.pop()
        if (u, v) in dual_edges or (v, u) in dual_edges:
            continue
        collector = {}
        q = deque([(u, []), (v, [])])
        visited = set()

        while q:
            x, y = q.popleft()
            visited.add(x)
            for y_ in graph[x]:
                if y_ in visited:
                    continue
                if y_ not in dual_graph[x] or y_ not in collector:
                    collector[y_] = u
                    collector[y] = u
                    q.append((y_, list((collector.keys()) & set((v, u)))))

        for key in collector:
            if key >= 0 and collector[key] != -1:
                dual_edges.remove(key)
                dual_edges.add(key + col + 1)

        collector.clear()
        collector.clear()

    for key in graph:
        if collector[key] != -1:
            d, c = collector[key], key
            for cd in dual_edges:
                if d in (cd[0], d + 2) and c in (cd[1], c + 2) and (c < d or key < 0 or 0 < collector[c] < 1):
                    dual_edges.remove(cd)
                elif c in (d + 2, c + 1) and (cd[0] in (d, d + 2) or cd[1] in (c, c + 2) or (d < 0 or key < 0 or 0 < collector[d] < 1)):
                    dual_edges.remove(cd)
        graph[key] = collector[key]

    return dual_graph

