from collections import deque

def get_linked_areas(matrix):
    rows, cols = len(matrix), len(matrix[0])
    queue = deque()
    linked_areas = set()

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 'B':
                color = 'B'
            else:
                color = 'W'
            queue.append((r, c, color))

    while queue:
        r, c, color = queue.popleft()
        linked_areas.add((r, c, color))
        directions = [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]
        for dr, dc in directions:
            if 0 <= dr < rows and 0 <= dc < cols:
                i, j = dr, dc
                while 0 <= i < rows and 0 <= j < cols:
                    if (i, j) in linked_areas:
                        matrix[i][j] = color
                        linked_areas.add((i, j, color))
                    i += dr
                    j += dc
    return linked_areas

def get_min_paintings(matrix):
    linked_areas = get_linked_areas(matrix)
    total_paintings = 0

    def dfs(i, j, bits):
        nonlocal total_paintings
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            ni, nj = i + dr, j + dc
            if 0 <= ni < len(matrix) and 0 <= nj < len(matrix[0]) and matrix[ni][nj] not in ('B', 'W'):
                if (ni, nj, bits & (1 << matrix[ni][nj])) not in linked_areas:
                    total_paintings += 1
                    bits |= (1 << matrix[ni][nj])
                    dfs(ni, nj, bits)

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] in ('B', 'W'):
                bits = 1 << matrix[i][j]
                dfs(i, j, bits)
                total_paintings += 1
    return total_paintings

