from collections import deque

def bfs(queue, n, m, colors):
    visited = set()
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                if (nx, ny) in queue or colors[nx][ny] != colors[x][y]:
                    queue.append((nx, ny))
                    visited.add((nx, ny))
                    visited |= visited.add((x, y))
    return len(visited)

def itinerary(n, m, colors):
    knowledges = deque([((0, 0), colors[0][0])])
    i = 0
    while i < (n + 1) * (m + 1) and knowledges:
        prev_state = knowledges.popleft()
        neighbors = deque()
        (x, y), colors[x][y] = prev_state
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                neighbors.append((colors[nx][ny], (nx, ny)))
        for d in neighbors:
            if x == n - 1 and y == m - 1:
                return i + 1
            if d[0] >= 0:
                knowledges.append(prev_state + (d[1],))
    return i + 1

