from heapq import heappush, heappop

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return distances

def construct_tree(n):
    tree = {}

    for i in range(1, n + 1):
        tree[i] = {}

    for i in range(n - 1):
        u, v, x = map(int, input().split())
        if x > 0:
            total_distance = x
        else:
            total_distance = abs(x // 1000 - (x % 1000))
        graph = [u, v]
        for neighbor in graph:
            weight = ((v - neighbor)**2 + (u - neighbor)**2)**0.5 if neighbor != u else 0
            graph[neighbor] = weight
        tree[x] = graph

    return tree

def solve(n):
    max_possible_multiples = n * n // 9
    visited = [False] + [True] * n
    numbers = {1}

    differences = [0]

    # Levelwise traversal to establish differences and get all numbers on the first level
    for _ in range(max_possible_multiples):
        new_numbers = set()

        for node, _ in enumerate(numbers):
            distances = dijkstra(tree, node)
            min_distance = float('inf')

            for neighbor, distance in distances.items():
                if not visited[neighbor]:
                    min_distance = min(min_distance, distance)
                    x = distances[neighbor] + node % 1000
                    y = distance + node // 1000
                    new_numbers.add(x - y)
                    num = x - (node + 1)
                    new_numbers.add(num)
                    new_numbers.add(num + 1)
                    difference = abs(num // 1000 - (num % 1000))
                    differences.append(difference)
                    visited[node] = True

        numbers = new_numbers
        if len(numbers) == 1:
            return

    # Insert other numbers such that their value of differences is used once
    used_differences = set()

    for difference in differences:
        if difference not in used_differences:
            use_multiple = max_possible_multiples // len(used_differences) * (len(used_differences) + 1)
            extracted_number = (difference * use_multiple % (sum(num // 1000 + num % 1000 for num in numbers[-use_multiple:])) + use_multiple) // (use_multiple + 1) - sum(log10(max(distance.solve())) for distance in numbers[-use_multiple:])
            numbers.add(extracted_number)
            used_differences.add(difference)

    return numbers

