import sys

MOD = 10**9 + 7

def simplify_expression(expression):
    if '(' in expression:
        brackets = expression.count('(')
        expression = '(' * brackets + expression
    stack = []
    for char in expression:
        if char == ')' and stack[-1] == '(':
            stack.pop()
        else:
            stack.append(char)
    if stack:
        raise ValueError("Invalid expression: mismatched parentheses")
    simplified = ''.join(filter(str.isdigit, expression))
    for i, d in enumerate(simplified):
        if i > 0:
            simplified = '0' * int(simplified[i-1]) + d + simplified
    return simplified[int(simplified[i-int(simplified[0])])] * int(simplified[0])

def solve(expression):
    simpl_eres = simplify_expression(expression)
    pow_2 = 1
    for d in simpl_eres:
        if '0' <= d <= '9':
            pow_2 = (pow_2 * 10 + int(d)) % MOD
    return pow_2

