import math

MOD = 10**9 + 7

def modular_pow(base, exp, mod):
    result = 1
    base = base % mod
    while(exp > 0):
        if(exp % 2):
            result = (result * base) % mod
        exp = exp >> 1
        base = (base * base) % mod
    return result

def merge_squares_with_shifts(m, n):
    total = 0
    prev = -1
    current = -1

    for i in range(1, n + 1):
        odd_res = (prev * 3 + lcs(prev, i - 1)) % MOD
        even_res = (current + lcs(prev, i - 1)) % MOD
        total += min(modular_pow(2, m - i, MOD), modular_pow(2, i, MOD)) * max(odd_res, even_res) % MOD
        prev, current = current, odd_res if i % 2 else even_res

    return total

def lcs(a, b, dp=None):
    if a == -1 or b == -1:
        return max(-1, max(a, b), 0)
    if dp is None:
        dp = [[0 for _ in range(b + 1)] for _ in range(a + 1)]
    if dp[a][b] > 0:
        return dp[a][b]
    if a == 0 or b == 0:
        return max(-1, max(a, b), 0)
    if a > 0 and b > 0 and not dp[a-1][b-1]:
        return lcs(a, b-1, dp) - lcs(a-1, b-1, dp)
    return max(max(lcs(a-1, b, dp), dp[a][b-1]), 0) - max(max(lcs(a-1, b-1, dp), lcs(a, b-1, dp)), 0)

