def minimal_paint_days(N, M, colors):
    current = ['#' * M]
    search = [list(line) for line in colors]
    changes = 0

    while True:
        next_states = set()
        for i in range(N):
            for j in range(M):
                current_state = ''.join([letter for line in search for letter in line])
                if len(next_states) <= M * N:
                    next_states.add(current_state)
                if line[i][j] != colors[i][j]:
                    for di, dj in [(1,0), (-1,0), (0,1), (0,-1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < N and 0 <= nj < M and search[ni][nj] != colors[ni][nj]:
                            next_states.add(current_state)
                            break

        new_search = [list(colors) for _ in range(N)]
        for state in next_states:
            if state not in current:
                changes += 1
                next_colors = [line[:] for line in search]
                for i in range(N):
                    for j in range(M):
                        if state[i][j] == '#':
                            if line[i][j] == 'B':
                                new_colors[i][j] = 'B'
                            elif line[i][j] == 'W':
                                new_colors[i][j] = 'W'
                        else:
                            if line[i][j] == 'B':
                                new_colors[i][j] = 'W'
                            elif line[i][j] == 'W':
                                new_colors[i][j] = 'B'

                for i in range(N):
                    search[i] = new_colors[i]

        if current_state in next_states:
            break

        current = next_states
        colors = new_search

    return changes

